import{_ as t,o as e,c as i,a2 as s}from"./chunks/framework.ChIlRNAd.js";const p=JSON.parse('{"title":"First Steps","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/first-steps.md","filePath":"en/guide/first-steps.md"}'),o={name:"en/guide/first-steps.md"};function n(r,a,l,c,h,u){return e(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="first-steps" tabindex="-1">First Steps <a class="header-anchor" href="#first-steps" aria-label="Permalink to &quot;First Steps&quot;">​</a></h1><p>This guide walks you through your first minutes with Nid.</p><hr><h2 id="create-your-account" tabindex="-1">Create your account <a class="header-anchor" href="#create-your-account" aria-label="Permalink to &quot;Create your account&quot;">​</a></h2><p>Open the app in your browser (default: <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>). The sign-in screen has two tabs: <strong>Sign in</strong> and <strong>Create account</strong>.</p><h3 id="local-account" tabindex="-1">Local account <a class="header-anchor" href="#local-account" aria-label="Permalink to &quot;Local account&quot;">​</a></h3><ol><li>Open the <strong>Create account</strong> tab</li><li>Enter your email and a password (8 characters minimum)</li><li>Confirm with <strong>Create account</strong></li></ol><h3 id="sign-in-with-a-provider" tabindex="-1">Sign in with a provider <a class="header-anchor" href="#sign-in-with-a-provider" aria-label="Permalink to &quot;Sign in with a provider&quot;">​</a></h3><p>If the administrator configured them, <strong>Sign in with Google</strong> buttons (or Microsoft, Discord, Facebook, LinkedIn, <strong>Sign in via SSO</strong>) appear under the form. Your name and avatar are fetched automatically.</p><div class="tip custom-block"><p class="custom-block-title">Account merging</p><p>If you first create a local account and then sign in with Google using the same email, both accounts are automatically merged.</p></div><p>If <a href="./settings.html#security">2FA</a> is on, a <strong>Two-step verification</strong> screen then asks for the 6-digit code from your authenticator app.</p><hr><h2 id="become-an-administrator" tabindex="-1">Become an administrator <a class="header-anchor" href="#become-an-administrator" aria-label="Permalink to &quot;Become an administrator&quot;">​</a></h2><p>The first user must be promoted to administrator. Three options:</p><h3 id="option-a-—-automatically-recommended" tabindex="-1">Option A — Automatically (recommended) <a class="header-anchor" href="#option-a-—-automatically-recommended" aria-label="Permalink to &quot;Option A — Automatically (recommended)&quot;">​</a></h3><p>Before creating your account, add the following to the <code>.env</code> file:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ADMIN_EMAIL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your@email.com</span></span></code></pre></div><p>The user who signs up with this email automatically gets the admin role.</p><h3 id="option-b-—-in-the-database" tabindex="-1">Option B — In the database <a class="header-anchor" href="#option-b-—-in-the-database" aria-label="Permalink to &quot;Option B — In the database&quot;">​</a></h3><p>If your account already exists:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> psql</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -U</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmailmanager</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gmailmanager</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;UPDATE users SET role = &#39;admin&#39; WHERE email = &#39;your@email.com&#39;;&quot;</span></span></code></pre></div><p>Log out and log back in for the new role to take effect.</p><h3 id="option-c-—-via-the-interface" tabindex="-1">Option C — Via the interface <a class="header-anchor" href="#option-c-—-via-the-interface" aria-label="Permalink to &quot;Option C — Via the interface&quot;">​</a></h3><p>An existing administrator can change a user&#39;s <strong>Role</strong> from <a href="./admin.html#users">Admin › Users</a>.</p><hr><h2 id="connect-a-gmail-account" tabindex="-1">Connect a Gmail account <a class="header-anchor" href="#connect-a-gmail-account" aria-label="Permalink to &quot;Connect a Gmail account&quot;">​</a></h2><p>As long as no Gmail account is connected, the Overview shows &quot;No Gmail account connected&quot; with the <strong>Connect a Gmail account</strong> link.</p><ol><li>Go to <strong>Settings › Gmail accounts</strong> (on mobile: <strong>More › Gmail accounts</strong>)</li><li>Click <strong>Add a Gmail account</strong></li><li>Allow access in the Google window (requested access: <code>gmail.modify</code>, <code>gmail.labels</code>)</li><li>Back in Nid, a message confirms &quot;Gmail account connected: …&quot;</li></ol><div class="warning custom-block"><p class="custom-block-title">Google warning screen</p><p>If your Google Cloud project is in &quot;Testing&quot; mode, a warning screen appears. Click <strong>Advanced</strong> → <strong>Go to nid (unsafe)</strong>. This is expected for personal self-hosted use.</p></div><p>Repeat for other accounts, within the limit set by the administrator (shown as &quot;N / max accounts&quot;). Pick the active account in the sidebar&#39;s <strong>Gmail Account</strong> selector (on mobile: the avatar menu). Every page shows that account&#39;s data.</p><hr><h2 id="your-first-cleanup" tabindex="-1">Your first cleanup <a class="header-anchor" href="#your-first-cleanup" aria-label="Permalink to &quot;Your first cleanup&quot;">​</a></h2><ol><li>Open <strong>Cleanup</strong> and click <strong>Scan the mailbox</strong>: Nid groups your newsletters and mailing-list mails by sender (the scan runs in the background, you can leave the page).</li><li>Sort by <strong>Size</strong> or <strong>Never opened</strong>.</li><li>On a sender, click <strong>Delete all</strong>: its mails go to the Gmail trash.</li><li>A toast &quot;Deleting N emails in 10 s&quot; appears with <strong>Undo</strong>: you have 10 seconds to change your mind.</li></ol><p>Details are in <a href="./cleanup.html">Cleanup</a>. To act on any Gmail search, see <a href="./mails.html">Mail</a>.</p><div class="tip custom-block"><p class="custom-block-title">Gmail trash</p><p>&quot;Delete&quot; moves mails to the <strong>Gmail trash</strong>, where Gmail keeps them 30 days before erasing them.</p></div><hr><h2 id="your-first-nas-backup" tabindex="-1">Your first NAS backup <a class="header-anchor" href="#your-first-nas-backup" aria-label="Permalink to &quot;Your first NAS backup&quot;">​</a></h2><ol><li>In <strong>Mail</strong>, run a search (e.g. <code>older_than:1y</code>)</li><li>Click <strong>Save all to the NAS</strong> (or select mails then <strong>Save to the NAS</strong>)</li><li>Progress shows on the page and in <a href="./activity.html">Activity</a></li></ol><p>Saved mails end up in <a href="./archives.html">Archives</a>, with full-text search. For regular backups, turn on the account&#39;s <strong>Automatic backup</strong> in <a href="./settings.html#gmail-accounts">Settings › Gmail accounts</a>.</p><hr><h2 id="what-s-next" tabindex="-1">What&#39;s next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next?&quot;">​</a></h2><ul><li><a href="./rules.html"><strong>Rules &amp; labels</strong></a> — automate sorting and cleanup</li><li><a href="./overview.html"><strong>Overview</strong></a> — your account status and suggestions</li><li><a href="./settings.html"><strong>Settings</strong></a> — 2FA, notifications, import/export</li></ul>`,42)])])}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
